import base64
import hashlib
import os
import secrets
from dataclasses import dataclass
from typing import Dict, Optional
from urllib.parse import urlencode

import requests

AUTH0_DOMAIN = os.getenv("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.getenv("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.getenv("AUTH0_CLIENT_SECRET")
AUTH0_REDIRECT_URI = os.getenv("AUTH0_REDIRECT_URI", "http://localhost:8000/callback")
AUTH0_AUDIENCE = os.getenv("AUTH0_AUDIENCE")

if not AUTH0_DOMAIN or not AUTH0_CLIENT_ID:
    raise ValueError("AUTH0_DOMAIN and AUTH0_CLIENT_ID must be set")

AUTH0_ISSUER = f"https://{AUTH0_DOMAIN}"
AUTH0_AUTHORIZE_URL = f"{AUTH0_ISSUER}/authorize"
AUTH0_TOKEN_URL = f"{AUTH0_ISSUER}/oauth/token"
AUTH0_USERINFO_URL = f"{AUTH0_ISSUER}/userinfo"


def _base64url_no_padding(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def generate_code_verifier() -> str:
    return _base64url_no_padding(secrets.token_bytes(32))


def generate_code_challenge(code_verifier: str) -> str:
    digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
    return _base64url_no_padding(digest)


@dataclass
class PKCELoginFlow:
    auth_url: str
    state: str
    code_verifier: str


class Auth0PKCEClient:
    def __init__(
        self,
        domain: str = AUTH0_DOMAIN,
        client_id: str = AUTH0_CLIENT_ID,
        redirect_uri: str = AUTH0_REDIRECT_URI,
        audience: Optional[str] = AUTH0_AUDIENCE,
        client_secret: Optional[str] = AUTH0_CLIENT_SECRET,
        session: Optional[requests.Session] = None,
    ):
        self.domain = domain
        self.client_id = client_id
        self.redirect_uri = redirect_uri
        self.audience = audience
        self.client_secret = client_secret
        self.session = session or requests.Session()

    def build_login_flow(self, scope: str = "openid profile email") -> PKCELoginFlow:
        code_verifier = generate_code_verifier()
        code_challenge = generate_code_challenge(code_verifier)
        state = secrets.token_urlsafe(32)

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience

        auth_url = f"{AUTH0_AUTHORIZE_URL}?{urlencode(params)}"
        return PKCELoginFlow(auth_url=auth_url, state=state, code_verifier=code_verifier)

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        if self.client_secret:
            payload["client_secret"] = self.client_secret

        response = self.session.post(AUTH0_TOKEN_URL, json=payload, timeout=30)
        response.raise_for_status()
        return response.json()

    def userinfo(self, access_token: str) -> Dict:
        response = self.session.get(
            AUTH0_USERINFO_URL,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def login_and_fetch_profile(self, code: str, code_verifier: str) -> Dict:
        token_response = self.exchange_code_for_tokens(code, code_verifier)
        access_token = token_response.get("access_token")
        if not access_token:
            raise ValueError("No access_token returned from Auth0 token endpoint")

        profile = self.userinfo(access_token)
        return {"tokens": token_response, "profile": profile}
